\begin{asy}
pair A=(0,0), B=(60,0), C=(60,-60), D=(0,-60), M=(0,-40), N=(20,-60);
pathpen=black;
D(MP("A",A,W)--MP("B",B,NE)--MP("C",C,SE)--MP("D",D,SW)--cycle);
D(B--MP("M",M,W));
D(B--MP("N",N,S));
D(CR(B,3));
